import{_ as o,o as r,c as d,a2 as e}from"./chunks/framework.DSoq407f.js";const c=JSON.parse('{"title":"支持的平台","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/supported.md","filePath":"platforms/supported.md","lastUpdated":1782304957000}'),a={name:"platforms/supported.md"};function s(n,t,l,i,h,g){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="支持的平台" tabindex="-1">支持的平台 <a class="header-anchor" href="#支持的平台" aria-label="Permalink to &quot;支持的平台&quot;">​</a></h1><blockquote><p><strong>你会学到</strong>：V3 支持哪些平台、各自怎么接入、什么是连接模式。</p></blockquote><p>V3 通过<strong>适配器</strong>接入各大即时通讯平台。得益于 <a href="./../xubp/overview">XUBP 协议</a>，同一份插件在所有平台通用，你只需关心接入配置。</p><h2 id="九大支持平台" tabindex="-1">九大支持平台 <a class="header-anchor" href="#九大支持平台" aria-label="Permalink to &quot;九大支持平台&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>适配器</th><th>典型连接模式</th></tr></thead><tbody><tr><td><strong>QQ 官方</strong></td><td>QQ 官方机器人</td><td>Webhook 回调</td></tr><tr><td><strong>QQ（OneBot）</strong></td><td>OneBot v11</td><td>反向 WebSocket</td></tr><tr><td><strong>Telegram</strong></td><td>Telegram Bot</td><td>长轮询</td></tr><tr><td><strong>Discord</strong></td><td>Discord Bot</td><td>正向 WebSocket</td></tr><tr><td><strong>KOOK</strong></td><td>KOOK Bot</td><td>WebSocket</td></tr><tr><td><strong>飞书</strong></td><td>飞书机器人</td><td>Webhook 回调</td></tr><tr><td><strong>钉钉</strong></td><td>钉钉机器人</td><td>Webhook 回调</td></tr><tr><td><strong>微信公众号</strong></td><td>公众号</td><td>Webhook 回调</td></tr><tr><td><strong>企业微信</strong></td><td>企业微信</td><td>Webhook 回调</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">平台会持续增加</p><p>V3 的适配器架构支持扩展新平台。如有新的平台需求，联系平台方。</p></div><h2 id="连接模式说明" tabindex="-1">连接模式说明 <a class="header-anchor" href="#连接模式说明" aria-label="Permalink to &quot;连接模式说明&quot;">​</a></h2><p>不同平台推送事件的方式不同，V3 支持四种连接模式：</p><table tabindex="0"><thead><tr><th>模式</th><th>方向</th><th>工作方式</th><th>典型平台</th></tr></thead><tbody><tr><td><strong>Webhook 回调</strong></td><td>平台 → 我们</td><td>平台主动把事件 POST 到我们的回调地址</td><td>QQ 官方、飞书、钉钉</td></tr><tr><td><strong>正向 WebSocket</strong></td><td>我们 → 平台</td><td>我们连到平台的 WS 网关接收事件</td><td>Discord</td></tr><tr><td><strong>反向 WebSocket</strong></td><td>平台 → 我们</td><td>平台的客户端连到我们开放的 WS</td><td>OneBot、Lagrange</td></tr><tr><td><strong>长轮询</strong></td><td>我们 → 平台</td><td>我们反复请求平台拉取新事件</td><td>Telegram</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">插件无感知</p><p>连接模式是<strong>适配器层面</strong>的事，插件完全不用关心。无论平台用哪种模式接入，插件看到的都是统一的 <a href="./../xubp/events">XUBP 事件</a>。</p></div><h2 id="接入一个平台" tabindex="-1">接入一个平台 <a class="header-anchor" href="#接入一个平台" aria-label="Permalink to &quot;接入一个平台&quot;">​</a></h2><p>在 V3 后台接入某个平台，大致流程：</p><ol><li><strong>创建机器人</strong>：在用户控制台创建一个机器人实例，选择对应平台适配器。</li><li><strong>填写平台凭证</strong>：填入该平台的应用 ID、Token、Secret 等（各平台不同）。</li><li><strong>配置连接</strong>： <ul><li>Webhook 类：把 V3 生成的回调地址填到平台后台。</li><li>WebSocket 类：确认 V3 能连到平台，或平台能连到 V3。</li><li>轮询类：填好 Token 即可。</li></ul></li><li><strong>启用机器人</strong>：启动后开始接收事件。</li></ol><p>每个平台的具体凭证获取方式，参考各平台官方文档。</p><div class="warning custom-block"><p class="custom-block-title">Webhook 需要 HTTPS</p><p>QQ 官方、飞书等 Webhook 类平台，要求回调地址必须是<strong>公网可访问的 HTTPS</strong>。请先配好 <a href="./../deploy/nginx">Nginx + SSL</a>。</p></div><h2 id="各平台事件支持" tabindex="-1">各平台事件支持 <a class="header-anchor" href="#各平台事件支持" aria-label="Permalink to &quot;各平台事件支持&quot;">​</a></h2><p>不同平台能提供的事件类型有差异。完整的事件支持情况见 <a href="./../xubp/events#跨平台事件映射">事件类型 · 跨平台映射</a>。</p><p>简单说：</p><ul><li><strong>消息类</strong>（群/私聊）：所有平台都支持。</li><li><strong>交互/按钮</strong>：QQ 官方、Discord、Telegram 等支持。</li><li><strong>表情表态</strong>：QQ 官方、Discord 等支持。</li><li><strong>频道相关</strong>：QQ 官方、Discord 等支持。</li></ul><p>不支持的类型，适配器会在对应平台标注 &quot;—&quot;，未来版本可能补齐。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>想开发跨平台插件 → <a href="./../plugin-dev/getting-started">插件开发</a></li><li>理解事件流转 → <a href="./../xubp/message-flow">消息流转</a></li></ul>',22)])])}const b=o(a,[["render",s]]);export{c as __pageData,b as default};
